<section class="page-banner"><div class="container"><div class="section-label">ACCOUNT SETTINGS</div><h1>My profile</h1><p>Update your student profile and password.</p></div></section><section class="section container narrow"><div class="card panel"><div class="profile-intro"><div class="profile-avatar"><?= e(name_initial($me['full_name'])) ?></div><div><strong><?= e($me['full_name']) ?></strong><div class="small-muted"><?= e(str_replace('_',' ',ucfirst($me['role']))) ?> · Joined <?= e(pretty_date($me['created_at'],'M Y')) ?></div></div></div><form action="<?= e(url('profile/save')) ?>" method="post" class="form-stack"><?= csrf_field() ?><label>Full name<input required name="full_name" value="<?= e($me['full_name']) ?>" minlength="3" maxlength="120"></label><label>Email address<input type="email" name="email" required maxlength="190" value="<?= e($me['email']) ?>"></label><label>Student number (cannot be changed by student)<input readonly value="<?= e($me['student_number']) ?>" maxlength="50"></label><label>Faculty<select name="faculty"><option value="">Not specified</option><?php foreach(faculty_options() as $f): ?><option value="<?= e($f) ?>" <?= $me['faculty']===$f?'selected':'' ?>><?= e($f) ?></option><?php endforeach; ?></select></label><hr><h3>Change password <small>(optional)</small></h3><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="10" maxlength="72" autocomplete="new-password"></label><button class="btn btn-primary" type="submit">Save changes</button></form></div></section>
